package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Shared household matching: canonicalizes the free-text fields that identify a household
 * (last name and address) so values that differ only in letter case or in the amount of
 * surrounding/internal whitespace compare equal. Used to detect when a new owner shares a
 * household with an existing one.
 */
final class Households {

    private Households() {
    }

    /**
     * Canonicalizes {@code value} for case-insensitive, whitespace-insensitive comparison:
     * trims the ends, collapses every run of whitespace to a single space and lower-cases
     * the result. Returns an empty string when {@code value} is {@code null}.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== EnsureUniqueHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request that would place a new owner in a household already occupied by
 * an existing owner — one sharing the same last name and address, compared case-insensitively
 * with collapsed whitespace (see {@link Households#normalize(String)}). A request may opt in
 * to a shared household by setting {@code sharesHousehold} true, in which case the check is
 * skipped.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = Households.normalize(request.getLastName());
        String address = Households.normalize(request.getAddress());
        for (Owner owner : ownerRepository.findAll()) {
            if (lastName.equals(Households.normalize(owner.getLastName()))
                    && address.equals(Households.normalize(owner.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== DuplicateHouseholdException.java =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link EnsureUniqueHousehold} when a create request would place a new owner in a
 * household (same last name and address) already occupied by an existing owner, unless the
 * request opted in with {@code sharesHousehold}. Carries the offending values for the
 * handler's message. Checked so it appears in the function's {@code throws} clause and routes
 * to an escalation.
 */
public class DuplicateHouseholdException extends Exception {

    private final String lastName;

    private final String address;

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner with the same last name already lives at this address: " + lastName
                + ", " + address);
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return lastName;
    }

    public String getAddress() {
        return address;
    }
}
